input.content:
/* Focused regression client for OpenLDAP ITS#10264 (NoD local data leak).
 *
 * A local loopback server (no external traffic) accepts one connection and
 * either:
 *   mode "nod"      : replies with an unsolicited RFC 4511 extended response
 *                     (messageID 0) carrying a non-empty matchedDN and
 *                     diagnosticMessage and the Notice-of-Disconnection OID;
 *   mode "positive" : replies with a normal bind success.
 *
 * The client opens a simple bind and then calls ldap_result(), which drives
 * try_read1msg().  In "nod" mode the vulnerable code stores the decoded
 * matchedDN / diagnosticMessage in the stack-local dummy_lr; without the fix
 * those allocations leak (detected by LeakSanitizer).
 */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <ldap.h>

/* LDAPMessage { messageID 0, extendedResp [APPLICATION 24] {
 *   resultCode 0, matchedDN "dnx", diagnosticMessage "errmsg",
 *   responseName [10] "1.3.6.1.4.1.1466.20036" } } */
static unsigned char nod_msg[] = {
	0x30, 0x2d,                         /* SEQUENCE, 45 bytes */
	0x02, 0x01, 0x00,                   /* messageID 0 */
	0x78, 0x28,                         /* extendedResp, 40 bytes */
	0x0a, 0x01, 0x00,                   /* resultCode success */
	0x04, 0x03, 'd', 'n', 'x',          /* matchedDN "dnx" */
	0x04, 0x06, 'e', 'r', 'r', 'm', 's', 'g', /* diagnosticMessage */
	0x8a, 0x16,                         /* responseName [10], 22 bytes */
	'1', '.', '3', '.', '6', '.', '1', '.', '4', '.', '1',
	'.', '1', '4', '6', '6', '.', '2', '0', '0', '3', '6'
};

/* LDAPMessage { messageID 1, bindResponse [APPLICATION 1] {
 *   resultCode 0, matchedDN "", diagnosticMessage "" } } */
static unsigned char bind_ok[] = {
	0x30, 0x0c,
	0x02, 0x01, 0x01,
	0x61, 0x07,
	0x0a, 0x01, 0x00,
	0x04, 0x00,
	0x04, 0x00
};

static int srv_fd;
static int positive_mode;

static void *server_fn(void *arg)
{
	struct sockaddr_in cli;
	socklen_t cl = sizeof(cli);
	unsigned char buf[4096];
	int c;
	ssize_t n;

	(void)arg;
	c = accept(srv_fd, (struct sockaddr *)&cli, &cl);
	if (c < 0) {
		return NULL;
	}
	/* consume the client bind request (best effort) */
	n = recv(c, buf, sizeof(buf), 0);
	(void)n;
	if (positive_mode) {
		send(c, bind_ok, sizeof(bind_ok), 0);
	} else {
		send(c, nod_msg, sizeof(nod_msg), 0);
	}
	usleep(200000);
	close(c);
	return NULL;
}

int main(int argc, char **argv)
{
	struct sockaddr_in a;
	socklen_t al;
	pthread_t th;
	char url[128];
	LDAP *ld = NULL;
	LDAPMessage *res = NULL;
	struct timeval tv = { 10, 0 };
	int port, msgid, rc, one = 1;

	positive_mode = (argc > 1 && strcmp(argv[1], "positive") == 0);

	srv_fd = socket(AF_INET, SOCK_STREAM, 0);
	if (srv_fd < 0) { perror("socket"); return 2; }
	setsockopt(srv_fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one));
	memset(&a, 0, sizeof(a));
	a.sin_family = AF_INET;
	a.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
	a.sin_port = 0;
	if (bind(srv_fd, (struct sockaddr *)&a, sizeof(a)) < 0) { perror("bind"); return 2; }
	if (listen(srv_fd, 1) < 0) { perror("listen"); return 2; }
	al = sizeof(a);
	getsockname(srv_fd, (struct sockaddr *)&a, &al);
	port = ntohs(a.sin_port);

	if (pthread_create(&th, NULL, server_fn, NULL) != 0) { perror("pthread_create"); return 2; }

	snprintf(url, sizeof(url), "ldap://127.0.0.1:%d", port);
	rc = ldap_initialize(&ld, url);
	if (rc != LDAP_SUCCESS) { fprintf(stderr, "ldap_initialize failed: %d\n", rc); return 3; }

	msgid = ldap_simple_bind(ld, "cn=admin", "secret");
	if (msgid < 0) { fprintf(stderr, "ldap_simple_bind failed: %d\n", msgid); return 3; }

	rc = ldap_result(ld, LDAP_RES_ANY, LDAP_MSG_ALL, &tv, &res);
	fprintf(stderr, "ldap_result rc=%d res=%p\n", rc, (void *)res);

	if (positive_mode) {
		if (rc != LDAP_RES_BIND) {
			fprintf(stderr, "POSITIVE_FAIL: expected LDAP_RES_BIND(%d), got %d\n",
				LDAP_RES_BIND, rc);
			if (res) ldap_msgfree(res);
			ldap_unbind_ext_s(ld, NULL, NULL);
			pthread_join(th, NULL);
			return 4;
		}
		if (res) ldap_msgfree(res);
		ldap_unbind_ext_s(ld, NULL, NULL);
		pthread_join(th, NULL);
		close(srv_fd);
		fprintf(stderr, "POSITIVE_OK\n");
		return 0;
	}

	/* NoD path: the library must not return a normal result. */
	if (res) ldap_msgfree(res);
	ldap_unbind_ext_s(ld, NULL, NULL);
	pthread_join(th, NULL);
	close(srv_fd);
	fprintf(stderr, "NOD_HANDLED rc=%d\n", rc);
	return 0;
}

